import { useEffect, useState } from 'react';
import { errorMessage, type MemberProfile } from '../../lib/session';
import {
  DEFAULT_SORT,
  EYEBROW,
  SEARCH_PLACEHOLDER,
  SUBTITLE,
  TITLE,
  fetchSentOffers,
  filterSentOffers,
  resultCountLabel,
  sortSentOffers,
  type SentOffer,
  type SortColumn,
  type SortDirection,
} from '../../lib/sent-offers';
import { SentOffersTable } from './SentOffersTable';
import styles from './SentOffers.module.css';

interface Props {
  profile: MemberProfile;
  onOpenThread?: (threadId: string) => void;
}

const noop = () => {};

/**
 * VND-01 · Mis Ofertas (vista del vendedor).
 *
 * La pantalla posee todo el estado: ofertas brutas, carga, error, texto de
 * búsqueda y ordenación. Cada render filtra y luego ordena — primero
 * `filterSentOffers`, después `sortSentOffers`; ese orden es contrato.
 */
export function SentOffers({ profile, onOpenThread }: Props) {
  const [offers, setOffers] = useState<SentOffer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const [sort, setSort] = useState<{ column: SortColumn; direction: SortDirection }>(DEFAULT_SORT);

  useEffect(() => {
    let active = true;
    setLoading(true);
    setError(null);
    fetchSentOffers(profile.orgId)
      .then((data) => {
        if (!active) return;
        setOffers(data);
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (!active) return;
        setError(errorMessage(err));
        setLoading(false);
      });
    return () => {
      active = false;
    };
  }, [profile.orgId]);

  const handleSort = (column: SortColumn) => {
    setSort((prev): { column: SortColumn; direction: SortDirection } =>
      prev.column === column
        ? { column, direction: prev.direction === 'asc' ? 'desc' : 'asc' }
        : { column, direction: 'asc' },
    );
  };

  // El orden de las operaciones es FILTRAR y luego ORDENAR. La lista original
  // nunca se muta: `sortSentOffers` devuelve una copia nueva.
  const filtradas = filterSentOffers(offers, query);
  const ordenadas = sortSentOffers(filtradas, sort.column, sort.direction);
  const hasQuery = query.trim().length > 0;

  return (
    <div className={styles.body} data-testid="selling-body" aria-busy={loading ? 'true' : 'false'}>
      <p className={styles.eyebrow}>{EYEBROW}</p>
      <h1 className={styles.title}>{TITLE}</h1>
      <p className={styles.subtitle}>{SUBTITLE}</p>

      {error !== null && (
        <div className={styles.errorBox} role="alert">
          {error}
        </div>
      )}

      {error === null && !loading && (
        <>
          <div className={styles.searchRow}>
            <div className={styles.searchWrap}>
              <input
                type="text"
                className={styles.searchInput}
                placeholder={SEARCH_PLACEHOLDER}
                value={query}
                onChange={(e) => setQuery(e.target.value)}
              />
              {hasQuery && (
                <button
                  type="button"
                  className={styles.clearButton}
                  onClick={() => setQuery('')}
                  aria-label="Limpiar búsqueda"
                >
                  ×
                </button>
              )}
            </div>
            <span className={styles.resultCount}>{resultCountLabel(filtradas.length)}</span>
          </div>

          <SentOffersTable
            offers={ordenadas}
            sort={sort}
            onSort={handleSort}
            onOpenThread={onOpenThread ?? noop}
            hasQuery={hasQuery}
          />
        </>
      )}
    </div>
  );
}

.tableWrap {
  overflow: auto;
  max-height: calc(100vh - 270px);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  /* El HTML aprobado usa blanco puro; el sistema de diseño no define un token
     para blanco, así que se usa la superficie clara más cercana. */
  background: var(--bw-warm-cream);
}

.table {
  width: 100%;
  border-collapse: collapse;
}

.th {
  padding: 9px 14px;
  text-align: left;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bw-steel-mist);
  background: var(--bw-surface-mist);
  border-bottom: 1px solid var(--bw-line-steel);
  white-space: nowrap;
  position: sticky;
  top: 0;
  z-index: 1;
  user-select: none;
}

.thSortable:hover .sortButton {
  color: var(--bw-ink-steel);
}

.sortButton {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0;
  margin: 0;
  border: none;
  background: none;
  font: inherit;
  color: inherit;
  cursor: pointer;
}

.sortIcon {
  font-style: normal;
  font-size: 10px;
  color: var(--bw-calibration-blue);
}

.sortIconNeutral {
  color: var(--bw-input-placeholder);
  opacity: 0.7;
}

.tbody tr:last-child .td {
  border-bottom: none;
}

.row:hover .td {
  background: var(--bw-row-hover-tint);
}

.td {
  padding: 10px 14px;
  font-size: 13px;
  color: var(--bw-ink-steel);
  border-bottom: 1px solid var(--bw-divider-mist);
  vertical-align: middle;
  white-space: nowrap;
}

.ref {
  display: block;
  font-family: var(--bw-font-mono);
  font-size: 12px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.brand {
  display: block;
  margin-top: 1px;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder);
}

.org {
  font-size: 12px;
  font-weight: 500;
}

.badge {
  display: inline-block;
  padding: 2px 7px;
  border-radius: 2px;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  letter-spacing: 0.05em;
  line-height: 1.4;
}

.statePendiente {
  background: var(--bw-badge-warning-bg);
  border: 1px solid var(--bw-badge-warning-border);
  color: var(--bw-warning);
}

.stateAceptada {
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  color: var(--bw-success-dark);
}

.stateRechazada {
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  color: var(--bw-sensitive-text);
}

.stateSuperada {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border);
  color: var(--bw-steel-mist);
}

.sentAt {
  font-family: var(--bw-font-mono);
  font-size: 11px;
  color: var(--bw-steel-mist);
}

.actionButton {
  height: 26px;
  padding: 0 10px;
  border-radius: 4px;
  font-family: var(--bw-font-body);
  font-size: 11px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: opacity 0.12s;
}

.actionPrimary {
  border: none;
  background: var(--bw-calibration-blue);
  color: var(--bw-on-dark-hover);
}

.actionPrimary:hover {
  opacity: 0.87;
}

.actionGhost {
  background: none;
  border: 1px solid var(--bw-line-steel-strong);
  color: var(--bw-steel-mist);
}

.actionGhost:hover {
  border-color: var(--bw-input-placeholder);
  color: var(--bw-ink-steel);
}

.emptyState {
  padding: 48px 20px;
  text-align: center;
  font-size: 13px;
  color: var(--bw-input-placeholder);
}

import {
  EMPTY_NO_MATCHES,
  EMPTY_NO_OFFERS,
  rowActionLabel,
  sentAtLabel,
  type SentOffer,
  type SortColumn,
  type SortDirection,
} from '../../lib/sent-offers';
import styles from './SentOffersTable.module.css';

interface Props {
  offers: SentOffer[];
  sort: { column: SortColumn; direction: SortDirection };
  onSort: (column: SortColumn) => void;
  onOpenThread: (threadId: string) => void;
  hasQuery: boolean;
}

/** Las cuatro cabeceras ordenables de la §5.1. 'Acciones' no es ordenable. */
const SORTABLE_COLUMNS: { key: SortColumn; label: string }[] = [
  { key: 'referencia', label: 'Referencia' },
  { key: 'organizacion', label: 'Organización' },
  { key: 'estado', label: 'Estado' },
  { key: 'fecha', label: 'Fecha' },
];

/**
 * Clases de badge por estado. Cuatro entradas, una por literal del CHECK de
 * 0003 (F-043): 'Superada por contraoferta' existe en el esquema aunque la
 * §5.2 no lo liste, y merece su propio tono neutro.
 */
const STATE_CLASS: Record<SentOffer['state'], string> = {
  Pendiente: styles.statePendiente,
  Aceptada: styles.stateAceptada,
  Rechazada: styles.stateRechazada,
  'Superada por contraoferta': styles.stateSuperada,
};

/**
 * Tabla de Mis Ofertas — presentacional.
 *
 * Recibe las filas ya filtradas y ya ordenadas y no vuelve a tocarlas.
 * El estado vacío vive aquí, dentro del componente, porque «no hay filas» es
 * un estado de la lista y no de la pantalla (misma lección que SRCH-01).
 */
export function SentOffersTable({ offers, sort, onSort, onOpenThread, hasQuery }: Props) {
  return (
    <div className={styles.tableWrap}>
      <table className={styles.table}>
        <thead>
          <tr>
            {SORTABLE_COLUMNS.map((col) => {
              const active = sort.column === col.key;
              const ariaSort = active
                ? sort.direction === 'asc'
                  ? 'ascending'
                  : 'descending'
                : 'none';
              return (
                <th
                  key={col.key}
                  scope="col"
                  aria-sort={ariaSort}
                  className={`${styles.th} ${styles.thSortable}`}
                >
                  {/*
                   * Cabecera ordenable como BOTÓN dentro del `<th>`: recibe
                   * foco, responde a teclado y el lector lo anuncia. El
                   * sentido se declara en `aria-sort` del `<th>`, no en la
                   * flecha, que va `aria-hidden`.
                   */}
                  <button type="button" className={styles.sortButton} onClick={() => onSort(col.key)}>
                    {col.label}
                    <span
                      aria-hidden="true"
                      className={`${styles.sortIcon} ${active ? '' : styles.sortIconNeutral}`}
                    >
                      {active ? (sort.direction === 'asc' ? '↑' : '↓') : '↕'}
                    </span>
                  </button>
                </th>
              );
            })}
            <th scope="col" className={styles.th}>
              Acciones
            </th>
          </tr>
        </thead>
        {offers.length > 0 && (
          <tbody className={styles.tbody}>
            {offers.map((offer) => (
              <tr
                key={offer.id}
                className={styles.row}
                data-testid="sent-offer-row"
                data-offer-id={offer.id}
              >
                <td className={styles.td}>
                  <span className={styles.ref}>{offer.partNumber ?? ''}</span>
                  {offer.brand ? <span className={styles.brand}>{offer.brand}</span> : null}
                </td>
                <td className={styles.td}>{offer.counterpartyName}</td>
                <td className={styles.td}>
                  {/*
                   * El literal EXACTO del esquema, sin uppercase — ni siquiera
                   * con CSS: 'Pendiente' no es 'PENDIENTE' (F-043).
                   */}
                  <span className={`${styles.badge} ${STATE_CLASS[offer.state]}`}>{offer.state}</span>
                </td>
                <td className={styles.td}>
                  <span className={styles.sentAt}>{sentAtLabel(offer.createdAt)}</span>
                </td>
                <td className={styles.td}>
                  <button
                    type="button"
                    className={`${styles.actionButton} ${offer.state === 'Aceptada' ? styles.actionPrimary : styles.actionGhost}`}
                    onClick={() => onOpenThread(offer.threadId)}
                  >
                    {rowActionLabel(offer.state)}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        )}
      </table>
      {offers.length === 0 && (
        <div className={styles.emptyState} role="status">
          {hasQuery ? EMPTY_NO_MATCHES : EMPTY_NO_OFFERS}
        </div>
      )}
    </div>
  );
}
